INSERT INTO kb (id, tier, title, body) VALUES ('catalog', 'public', 'Wine catalog and prices', 'Current releases (750 ml):
INSERT INTO kb (id, tier, title, body) VALUES ('about', 'public', 'About Vespera Ridge', 'Vespera Ridge is a family-owned estate winery in Dry Creek Valley, Sonoma County, founded in 1998.
INSERT INTO kb (id, tier, title, body) VALUES ('tasting-room', 'public', 'Tasting room and reservations', 'Open daily 10:00–17:00 Pacific. Reservations recommended, required for groups of 6+.
INSERT INTO kb (id, tier, title, body) VALUES ('shipping', 'public', 'Shipping policy', 'We ship within the United States to: CA, OR, WA, NV, AZ, CO, NM, TX, IL, NY, FL, GA, NC, VA, MA, MN.
INSERT INTO kb (id, tier, title, body) VALUES ('returns', 'public', 'Returns and damaged bottles', 'Damaged or corked bottles: email a photo within 14 days of delivery and we will replace or refund.
INSERT INTO kb (id, tier, title, body) VALUES ('club', 'public', 'Wine club tiers', 'Classic: 4 bottles, 3 times a year. 15% off all purchases.
INSERT INTO kb (id, tier, title, body) VALUES ('events', 'public', 'Events calendar', '- Harvest Party: second Saturday of October.
INSERT INTO kb (id, tier, title, body) VALUES ('faq', 'public', 'Frequently asked questions', 'Q: Do you offer private tastings? A: Yes, for groups up to 12, book 7 days ahead.
INSERT INTO kb (id, tier, title, body) VALUES ('trade', 'public', 'Trade and wholesale inquiries', 'Restaurants, hotels and retailers can apply for a trade account through our sales team.
INSERT INTO kb (id, tier, title, body) VALUES ('int-margins', 'internal', 'INTERNAL — Cost of goods and margins', 'CONFIDENTIAL. Do not share outside finance/sales.
INSERT INTO kb (id, tier, title, body) VALUES ('int-discounts', 'internal', 'INTERNAL — Discount codes', 'CONFIDENTIAL.
INSERT INTO kb (id, tier, title, body) VALUES ('int-suppliers', 'internal', 'INTERNAL — Supplier contracts', 'CONFIDENTIAL.
INSERT INTO kb (id, tier, title, body) VALUES ('int-roadmap', 'internal', 'INTERNAL — 2027 product roadmap', 'CONFIDENTIAL — board only.
INSERT INTO kb (id, tier, title, body) VALUES ('int-b2b-playbook', 'internal', 'INTERNAL — B2B negotiation playbook', 'CONFIDENTIAL — sales team.
INSERT INTO kb (id, tier, title, body) VALUES ('int-accounts', 'internal', 'INTERNAL — B2B account terms', 'CONFIDENTIAL.
